const data = $json;
const config = data.context?.config;
if (!config) throw new Error('MarketPulse configuration is missing');
if (!config.queries.length) throw new Error('At least one search query is required');
if (!config.sources.length) throw new Error('At least one marketplace source is required');
const unsafe = config.queries.filter(q => q.length > 120 || /[<>\u0000-\u001F]/.test(q));
if (unsafe.length) throw new Error('Unsafe or oversized queries: ' + unsafe.join(', '));
const weightTotal = Object.values(config.scoring.opportunity_weights).reduce((sum, value) => sum + Number(value), 0);
if (Math.abs(weightTotal - 1) > 0.001) throw new Error('Opportunity scoring weights must total 1.0');
if (config.integrations.enabled) {
  const endpoints = {
    telegram_api_url: config.integrations.telegram_api_url,
    slack_webhook_url: config.integrations.slack_webhook_url,
    warehouse_webhook_url: config.integrations.warehouse_webhook_url
  };
  const invalidEndpoints = Object.entries(endpoints)
    .filter(([, value]) => {
      const normalized = String(value);
      return !normalized.toLowerCase().startsWith('https://') || normalized.includes('<') || normalized.includes('SET/ME') || normalized.includes('example.invalid');
    })
    .map(([name]) => name);
  if (!config.integrations.telegram_chat_id || /<SET_CHAT_ID>/i.test(config.integrations.telegram_chat_id)) invalidEndpoints.push('telegram_chat_id');
  if (invalidEndpoints.length) throw new Error('External delivery is enabled but runtime configuration is incomplete: ' + [...new Set(invalidEndpoints)].join(', '));
}
const runId = 'mpr_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
return [{ json: {
  ...data,
  context: {
    ...data.context,
    run_id: runId,
