  }
} }];

const context = $json.context;
const templates = [
  { query: 'беспроводной мини пылесос', category: 'Home appliances', title: 'Беспроводной мини-пылесос для дома и автомобиля', price: 2490, rank: 4, previousRank: 19, rating: 4.8, reviews: 1460, previousReviews: 1170, sales: 920, previousSales: 610, sellers: 12, costRatio: 0.31, delivery: 2 },
