const sourceCatalog = [
  { id: 'wildberries', prefix: 'WB', price: 0.94, rank: -1, reviews: 1.18, sales: 1.16, seller: 1.25 },
  { id: 'ozon', prefix: 'OZ', price: 1.04, rank: 2, reviews: 0.92, sales: 0.96, seller: 0.90 },
