  raw_products: rawProducts,
  source_health: sources.map(source => ({
    source: source.id,
    requests: activeTemplates.length,
    successful_requests: templates.length,
    failed_requests: 0,
    records: rawProducts.filter(product => product.marketplace === source.id).length,
    health: 'healthy'
  })),
  request_log: []
} }];

const { context } = $json;
const { config } = context;
const requests = [];
let sequence = 0;
for (const query of config.queries) {
  for (const source of config.sources) {
    sequence += 1;
    const encoded = encodeURIComponent(query);
    let requestUrl;
    if (source === 'wildberries') {
      requestUrl = 'https://search.wb.ru/exactmatch/ru/common/v18/search?ab_testing=false&appType=1&curr=rub&dest=' + encodeURIComponent(config.collection.destination_id) + '&hide_dtype=13&lang=ru&page=1&query=' + encoded + '&resultset=catalog&sort=popular&spp=30&suppressSpellcheck=false';
    } else if (source === 'ozon') {
      requestUrl = 'https://www.ozon.ru/api/entrypoint-api.bx/page/json/v2?url=/search/?text=' + encoded + '&sorting=rating';
    } else {
      requestUrl = 'https://market.yandex.ru/search?text=' + encoded + '&how=dpop';
    }
    requests.push({ json: {
      context,
      request: {
        sequence,
        source,
        query,
        url: requestUrl,
        requested_at: new Date().toISOString()
      }
    } });
  }
}
return requests;

return $input.all().map((item, index) => ({
  json: {
    ...item.json,
    request: {
      ...item.json.request,
      request_id: item.json.context.run_id + '_req_' + String(index + 1).padStart(3, '0'),
      started_at_ms: Date.now(),
      policy: {
        batch_size: item.json.context.config.collection.request_batch_size,
        interval_ms: item.json.context.config.collection.request_batch_interval_ms,
        max_results: item.json.context.config.collection.max_results_per_query
      }
    }
  },
  pairedItem: { item: index }
}));

const inputs = $input.all();
const first = inputs[0]?.json || {};
const context = first.context;
const maxPerQuery = context?.config?.collection?.max_results_per_query || 20;
const products = [];
const requestLog = [];

const numberFrom = value => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value !== 'string') return 0;
  const normalized = value.replace(/[^0-9,.-]/g, '').replace(/,(?=\d{1,2}$)/, '.');
  return Number(normalized.replace(/,/g, '')) || 0;
};

const parseJson = value => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
};

const collectCandidateObjects = (root, limit = 5000) => {
  const candidates = [];
  const queue = [{ value: root, depth: 0 }];
  let visited = 0;
  while (queue.length && visited < limit) {
    const { value, depth } = queue.shift();
    visited += 1;
    if (depth > 12 || value == null) continue;
    if (typeof value === 'string' && /^[\[{]/.test(value.trim())) {
      const parsed = parseJson(value);
      if (parsed) queue.push({ value: parsed, depth: depth + 1 });
      continue;
    }
    if (Array.isArray(value)) {
      for (const child of value) queue.push({ value: child, depth: depth + 1 });
      continue;
    }
    if (typeof value !== 'object') continue;
    const title = value.title || value.name || value.productName || value.fullName;
    const sku = value.sku || value.id || value.productId || value.offerId || value.shopSku;
    const price = value.price || value.finalPrice || value.salePrice || value.currentPrice || value.offers?.price;
    if (title && sku && price) candidates.push(value);
    for (const child of Object.values(value)) queue.push({ value: child, depth: depth + 1 });
  }
  return candidates;
};

for (const item of inputs) {
  const data = item.json;
  const request = data.request || {};
  const source = request.source;
  const statusCode = Number(data.statusCode || data.status_code || (data.error ? 0 : 200));
  const rawBody = data.body ?? '';
  let extracted = [];
  let parseError = null;
  try {
    if (source === 'wildberries') {
      const payload = parseJson(rawBody) || rawBody || {};
      const rows = payload?.data?.products || payload?.products || [];
      extracted = rows.slice(0, maxPerQuery).map((row, index) => ({
        raw_source: source,
        marketplace: source,
        query: request.query,
        category: row.entity || row.subjectName || row.category || null,
        sku: String(row.id || row.nmId || ''),
        title: row.name || row.title || '',
        brand: row.brand || null,
        seller_name: row.supplier || row.supplierName || null,
        price: Number(row.salePriceU || row.priceU || 0) / 100,
        old_price: Number(row.priceU || row.salePriceU || 0) / 100,
        currency: 'RUB',
        rating: Number(row.reviewRating || row.rating || 0),
        reviews_count: Number(row.feedbacks || row.reviewCount || 0),
        seller_count: Number(row.supplierCount || 1),
        current_rank: index + 1,
        sales_30d_proxy: Number(row.ordersCount || row.feedbacks || 0),
        delivery_days: Number(row.deliveryDays || 0),
        in_stock: Number(row.totalQuantity || row.quantity || 1) > 0,
        sponsored: Boolean(row.promoTextCard || row.isAdvert),
        url: 'https://www.wildberries.ru/catalog/' + String(row.id || row.nmId || '') + '/detail.aspx',
        image_url: row.imageUrl || null,
        captured_at: new Date().toISOString(),
        raw_payload: row
      }));
    } else {
      let roots = [];
      const direct = parseJson(rawBody);
      if (direct) roots.push(direct);
      if (!direct && typeof rawBody === 'string') {
        const scripts = [...rawBody.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
        for (const match of scripts) {
          const parsed = parseJson(match[1].trim());
          if (parsed) roots.push(parsed);
        }
        const nextData = rawBody.match(/<script[^>]+id=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/i);
        if (nextData) {
          const parsed = parseJson(nextData[1].trim());
          if (parsed) roots.push(parsed);
        }
      }
      const seen = new Set();
      const candidates = roots.flatMap(root => collectCandidateObjects(root));
      for (const [index, row] of candidates.entries()) {
        if (extracted.length >= maxPerQuery) break;
        const sku = String(row.sku || row.id || row.productId || row.offerId || row.shopSku || '');
        if (!sku || seen.has(sku)) continue;
        seen.add(sku);
        const offers = row.offers || row.offer || {};
        const rating = row.rating || row.aggregateRating?.ratingValue || row.reviewRating || 0;
        const reviews = row.reviewsCount || row.reviewCount || row.aggregateRating?.reviewCount || row.feedbacks || 0;
        const currentPrice = row.finalPrice || row.salePrice || row.currentPrice || row.price || offers.price || row.priceValue;
        const oldPrice = row.originalPrice || row.oldPrice || row.fullPrice || offers.highPrice || currentPrice;
        extracted.push({
          raw_source: source,
          marketplace: source,
          query: request.query,
          category: row.category || row.categoryName || row.breadcrumbs?.slice?.(-1)?.[0] || null,
          sku,
          title: row.title || row.name || row.productName || row.fullName || '',
          brand: row.brand?.name || row.brand || row.vendor || null,
          seller_name: row.seller?.name || row.shopName || row.sellerName || null,
          price: numberFrom(String(currentPrice ?? '')),
          old_price: numberFrom(String(oldPrice ?? currentPrice ?? '')),
          currency: row.priceCurrency || offers.priceCurrency || 'RUB',
          rating: numberFrom(String(rating)),
          reviews_count: numberFrom(String(reviews)),
          seller_count: Number(row.sellerCount || row.offerCount || 1),
          current_rank: index + 1,
          sales_30d_proxy: Number(row.salesCount || row.ordersCount || reviews || 0),
          delivery_days: Number(row.deliveryDays || 0),
          in_stock: row.available !== false && row.availability !== 'OutOfStock',
          sponsored: Boolean(row.isAdv || row.sponsored || row.isPromoted),
          url: row.url || row.link || (source === 'ozon' ? 'https://www.ozon.ru/search/?text=' + encodeURIComponent(request.query) : 'https://market.yandex.ru/search?text=' + encodeURIComponent(request.query)),
          image_url: row.image || row.imageUrl || row.pictures?.[0] || null,
          captured_at: new Date().toISOString(),
          raw_payload: row
        });
      }
    }
  } catch (error) {
    parseError = error.message;
  }
  products.push(...extracted);
  requestLog.push({
    request_id: request.request_id,
    source,
    query: request.query,
    status_code: statusCode,
    duration_ms: Math.max(0, Date.now() - Number(request.started_at_ms || Date.now())),
    records: extracted.length,
    successful: statusCode >= 200 && statusCode < 400 && !parseError,
    error: parseError || data.error?.message || data.message || null
  });
}

const sourceHealth = (context?.config?.sources || []).map(source => {
  const rows = requestLog.filter(row => row.source === source);
  const successful = rows.filter(row => row.successful).length;
  const records = rows.reduce((sum, row) => sum + row.records, 0);
  return {
    source,
    requests: rows.length,
    successful_requests: successful,
    failed_requests: rows.length - successful,
    records,
    health: successful === rows.length && records > 0 ? 'healthy' : successful > 0 ? 'degraded' : 'down'
  };
});

return [{ json: {
  context,
  collection_mode: 'live',
  raw_products: products,
  source_health: sourceHealth,
  request_log: requestLog
} }];

