const headers = ['rank','marketplace','sku','query','category','title','price_rub','rating','reviews','opportunity_score','demand_score','momentum_score','competition_index','margin_percent','risk_level','trend_stage','url'];
const escape = value => {
  const text = String(value ?? '');
  return /[",\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
};
const rows = ($json.report.top_opportunities || []).map(product => [
  product.global_rank,
  product.marketplace,
  product.product_key.split(':').slice(1).join(':'),
  product.query,
  product.category,
  product.title,
  product.price,
  product.rating,
  product.reviews_count,
  product.opportunity_score,
  product.demand_score,
  product.momentum_score,
  product.competition_index,
  product.margin_percent,
  product.risk_level,
  product.trend_stage,
  product.url
].map(escape).join(','));
return [{ json: { csv_export: [headers.join(','), ...rows].join('\n'), csv_filename: 'marketpulse_' + $json.context.run_id + '.csv' } }];

return [{ json: {
  api_envelope: {
    success: true,
    report_id: $json.report.report_id,
    generated_at: $json.report.generated_at,
    mode: $json.report.mode,
    kpis: $json.report.kpis,
    opportunities: $json.report.top_opportunities,
    categories: $json.report.category_insights,
    cross_market_gaps: $json.report.cross_market_gaps,
    selected_products: $json.report.selected_products,
    source_health: $json.report.source_health,
    data_quality: $json.report.data_quality
  }
} }];

const store = $getWorkflowStaticData('global');
const report = $json.report;
store.marketpulse_latest = {
  ...report,
  markdown_digest: $json.markdown_digest,
  csv_export: $json.csv_export,
  csv_filename: $json.csv_filename,
  api_envelope: $json.api_envelope,
  persisted_at: new Date().toISOString()
};
store.marketpulse_runs = Array.isArray(store.marketpulse_runs) ? store.marketpulse_runs : [];
store.marketpulse_runs.unshift({
  run_id: report.run_id,
  report_id: report.report_id,
  generated_at: report.generated_at,
  mode: report.mode,
  product_count: report.product_count,
  average_score: report.kpis.average_score,
  breakout_products: report.kpis.breakout_products,
  source_success_rate: report.kpis.source_success_rate
});
store.marketpulse_runs = store.marketpulse_runs.slice(0, 30);
if (!$json.context.config.demo_mode) {
  store.marketpulse_product_state = store.marketpulse_product_state || {};
  for (const product of $json.scored_products || []) {
    store.marketpulse_product_state[product.product_key] = {
      rank: product.current_rank,
      reviews_count: product.reviews_count,
      sales_30d_proxy: product.sales_30d_proxy,
      price: product.price,
      captured_at: report.generated_at
    };
  }
  const entries = Object.entries(store.marketpulse_product_state);
  if (entries.length > 2000) {
    entries.sort((a, b) => new Date(b[1].captured_at).getTime() - new Date(a[1].captured_at).getTime());
    store.marketpulse_product_state = Object.fromEntries(entries.slice(0, 2000));
  }
}
return [{ json: {
  ...$json,
  persistence: {
    snapshot_staged: true,
    durable_persistence_expected: $json.context.trigger_type !== 'manual',
    persistence_note: $json.context.trigger_type === 'manual' ? 'n8n does not save workflow static data after manual test executions' : 'static data is committed after a successful production execution',
    retained_run_summaries: store.marketpulse_runs.length,
    historical_product_keys: Object.keys(store.marketpulse_product_state || {}).length
  }
} }];

const items = $input.all().map(item => item.json);
let base = items.find(item => item.report) || null;
if (!base) {
  try { base = $('State · Stage Latest Radar Snapshot').first().json; } catch {}
}
base = base || {};
const status = {
  mode: 'live_integrations',
  telegram_attempted: items.some(item => Object.prototype.hasOwnProperty.call(item, 'telegram_delivery')),
  slack_attempted: items.some(item => Object.prototype.hasOwnProperty.call(item, 'slack_delivery')),
  warehouse_attempted: items.some(item => Object.prototype.hasOwnProperty.call(item, 'warehouse_delivery')),
  response_items: items.length,
  completed_at: new Date().toISOString()
};
return [{ json: { ...base, delivery_status: status } }];

return [{ json: {
  ...$json,
  delivery_status: {
    mode: 'skipped',
    reason: $json.context.config.demo_mode ? 'demo_mode' : 'integrations_disabled',
    completed_at: new Date().toISOString()
  }
} }];

const store = $getWorkflowStaticData('global');
const latest = store.marketpulse_latest || null;
return [{ json: latest ? {
  success: true,
  generated_at: new Date().toISOString(),
  snapshot_age_minutes: Number(((Date.now() - new Date(latest.generated_at).getTime()) / 60000).toFixed(2)),
  report: latest.api_envelope || latest
} : {
  success: false,
  generated_at: new Date().toISOString(),
  message: 'No MarketPulse snapshot exists. Run the demo or a live scan first.'
} }];

const store = $getWorkflowStaticData('global');
const latest = store.marketpulse_latest || null;
const errors = Array.isArray(store.marketpulse_errors) ? store.marketpulse_errors : [];
const ageHours = latest ? (Date.now() - new Date(latest.generated_at).getTime()) / 3600000 : null;
const sourceHealth = latest?.source_health || [];
const overall = !latest ? 'unknown' : ageHours > 30 ? 'stale' : sourceHealth.some(source => source.health === 'down') ? 'degraded' : 'healthy';
return [{ json: {
  success: true,
  generated_at: new Date().toISOString(),
  overall_status: overall,
  latest_snapshot_at: latest?.generated_at || null,
  snapshot_age_hours: ageHours == null ? null : Number(ageHours.toFixed(2)),
  source_health: sourceHealth,
  retained_runs: (store.marketpulse_runs || []).length,
  historical_products: Object.keys(store.marketpulse_product_state || {}).length,
  recent_error_count: errors.filter(error => Date.now() - new Date(error.occurred_at).getTime() < 86400000).length,
  latest_error: errors[0] ? {
    occurred_at: errors[0].occurred_at,
    last_node: errors[0].last_node,
    error_name: errors[0].error_name,
    error_message: errors[0].error_message
  } : null
} }];

const store = $getWorkflowStaticData('global');
const payload = $json.body && typeof $json.body === 'object' && !Array.isArray($json.body) ? $json.body : $json;
const clip = (value, limit = 500) => String(value ?? '').replace(/[\u0000-\u001F]/g, ' ').trim().slice(0, limit);
store.marketpulse_errors = Array.isArray(store.marketpulse_errors) ? store.marketpulse_errors : [];
const event = {
  occurred_at: new Date().toISOString(),
  workflow_ref: clip(payload.workflow?.id || payload.workflow_id, 120) || null,
  workflow_name: clip(payload.workflow?.name || payload.workflow_name || 'MarketPulse', 160),
  execution_ref: clip(payload.execution?.id || payload.execution_id, 120) || null,
  last_node: clip(payload.execution?.lastNodeExecuted || payload.last_node, 160) || null,
  error_name: clip(payload.execution?.error?.name || payload.error?.name || payload.error_name || 'WorkflowError', 160),
  error_message: clip(payload.execution?.error?.message || payload.error?.message || payload.error_message || 'Unknown MarketPulse failure', 1000)
};
store.marketpulse_errors.unshift(event);
store.marketpulse_errors = store.marketpulse_errors.slice(0, 50);
return [{ json: { success: true, recorded: true, event } }];
